set -euo pipefail; SDK="${ANDROID_SDK_ROOT:-${ANDROID_HOME:-$HOME/Library/Android/sdk}}"; ADB="$SDK/platform-tools/adb"; SERIAL=RFCT70L7E8J; python3 - <<'PY'
import os,re,subprocess,time,xml.etree.ElementTree as ET
SDK=os.path.expanduser(os.environ.get('ANDROID_SDK_ROOT') or os.environ.get('ANDROID_HOME') or '~/Library/Android/sdk'); adb=SDK+'/platform-tools/adb'; serial='RFCT70L7E8J'
def sh(*args): return subprocess.run([adb,'-s',serial,*args],check=True,capture_output=True,text=True)
def dump(name):
 sh('shell','uiautomator','dump',f'/sdcard/{name}.xml'); sh('pull',f'/sdcard/{name}.xml',f'/tmp/{name}.xml'); return ET.parse(f'/tmp/{name}.xml').getroot()
def center(bounds):
 m=re.match(r'\[(\d+),(\d+)\]\[(\d+),(\d+)\]',bounds); assert m,bounds; x1,y1,x2,y2=map(int,m.groups()); return str((x1+x2)//2),str((y1+y2)//2)
def tap(node): x,y=center(node.attrib['bounds']); sh('shell','input','tap',x,y); time.sleep(2)
time.sleep(2); root=dump('sl-wifi-scan-start')
vals=[(n,n.attrib.get('text','').strip(),n.attrib.get('content-desc','').strip()) for n in root.iter('node')]
if not any(d in ('Plug settings','Ustawienia gniazdka') for _,_,d in vals):
 targets=[n for n,t,d in vals if '· Bluetooth' in d]
 if not targets:
  print('START_UI');
  for n,t,d in vals:
   if t or d: print(repr(t),repr(d),n.attrib.get('bounds',''))
  raise SystemExit('No Bluetooth Plug detail target found')
 tap(targets[0]); root=dump('sl-wifi-scan-detail'); vals=[(n,n.attrib.get('text','').strip(),n.attrib.get('content-desc','').strip()) for n in root.iter('node')]
tabs=[n for n,t,d in vals if d in ('Plug settings','Ustawienia gniazdka')]; assert len(tabs)==1,[(t,d) for _,t,d in vals if t or d]; tap(tabs[0]); root=dump('sl-wifi-scan-device'); vals=[(n,n.attrib.get('text','').strip(),n.attrib.get('content-desc','').strip()) for n in root.iter('node')]
scan=[n for n,t,d in vals if t in ('Scan networks','Skanuj sieci') or d in ('Scan networks','Skanuj sieci')]; assert len(scan)==1,[(t,d) for _,t,d in vals if t or d]; tap(scan[0]); time.sleep(10); root=dump('sl-wifi-scan-after'); print('AFTER_SCAN_UI')
for n in root.iter('node'):
 t=n.attrib.get('text','').strip(); d=n.attrib.get('content-desc','').strip();
 if t or d: print(repr(t),repr(d),n.attrib.get('bounds',''))
PY
